let MAP = $('🗺️ خريطة المهن من المستودع').first().json;
if (MAP && typeof MAP.data === 'string') { try { MAP = JSON.parse(MAP.data); } catch (e) { throw new Error('خريطة المهن ليست JSON صالحاً: ' + String(e.message).slice(0, 120)); } }
if (!MAP || !MAP.map || !Array.isArray(MAP.labels) || MAP.v !== 1) throw new Error('خريطة المهن غير مقروءة من المستودع');
const UNC = 'غير مصنّف | Unclassified';
const CONF = { h: 'عالية', m: 'متوسطة', l: 'منخفضة' };
const key = (t) => String(t == null ? '' : t).replace(/^ +| +$/g, '').replace(/[A-Z]/g, (c) => c.toLowerCase());
function txt(p) { const a = (p && p.rich_text) || (p && p.title) || []; let s = ''; for (let i = 0; i < a.length; i++) s += String(a[i].plain_text || ''); return s; }
const rows = $input.all();
const out = [];
for (let i = 0; i < rows.length; i++) {
  const row = rows[i].json || {};
  if (!row.id) continue;
  const props = row.properties || {};
  const title = txt(props['Original Position']);
  const e = MAP.map[key(title)];
  const label = e ? MAP.labels[e[0]] : UNC;
  const conf = e ? CONF[e[1]] : 'منخفضة';
  const body = { properties: { 'المهنة الموحّدة': { select: { name: label } }, 'ثقة المهنة': { select: { name: conf } } } };
  out.push({ json: { pageId: row.id, label: label, conf: conf, mapped: !!e, title: title, bodyJson: JSON.stringify(body) } });
}
return out;

const src = $('🧭 المهنة من الخريطة').all().map((x) => x.json);
const res = $input.all().map((x) => x.json);
let ok = 0, failed = 0; const errs = [];
for (let i = 0; i < res.length; i++) { const r = res[i]; if (r && r.object === 'page' && r.id) ok++; else { failed++; if (errs.length < 10) errs.push(String((r && (r.message || (r.error && r.error.message))) || 'unknown').slice(0, 200)); } }
let mapped = 0, unc = 0; const byLabel = {};
for (let i = 0; i < src.length; i++) { if (src[i].mapped) mapped++; else unc++; byLabel[src[i].label] = (byLabel[src[i].label] || 0) + 1; }
const top = Object.entries(byLabel).sort((a, b) => b[1] - a[1]).slice(0, 15);
return [{ json: { rows: src.length, written: ok, failed: failed, mapped: mapped, notInMapUnclassified: unc, top: top, errors: errs, finishedAt: new Date().toISOString() } }];
